namespace ghidra.feature.vt.gui.actions;





using docking;
using docking.action;
using generic.theme;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.provider.onetomany;
using ghidra.util;

public class SetVTMatchFromOneToManyAction : DockingAction {

	private static readonly string MENU_GROUP = VTPlugin.VT_MAIN_MENU_GROUP;
	public static readonly Icon SET_MATCH_ICON =
		new GIcon("icon.version.tracking.action.match.one.to.many");

	VTController controller;

	public SetVTMatchFromOneToManyAction(VTController controller, bool addToToolbar) : base("Select Same Match In Version Tracking Matches Table", VTPlugin.OWNER)
    {
		this.controller = controller;

		if (addToToolbar) {
			setToolBarData(new ToolBarData(SET_MATCH_ICON, MENU_GROUP));
		}
		MenuData menuData = new MenuData(new string[] { "Select Match in VT Matches Table" },
			SET_MATCH_ICON, MENU_GROUP);
		setPopupMenuData(menuData);
		setEnabled(false);
		setHelpLocation(new HelpLocation("VersionTrackingPlugin",
			"Select_Same_Match_In_Version_Tracking_Matches_Table"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (context is VTMatchOneToManyContext) {
			VTMatch match = getSelectedMatch((VTMatchOneToManyContext) context);
			if (match != null) {
				controller.setSelectedMatch(match);
			}
		}
	}

	private VTMatch getSelectedMatch(VTMatchOneToManyContext context) {
		List<VTMatch> selectedMatches = context.getSelectedMatches();
		if (selectedMatches.size() == 1) {
			return selectedMatches.get(0);
		}
		return null;
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (context is VTMatchOneToManyContext) {
			VTMatch match = getSelectedMatch((VTMatchOneToManyContext) context);
			return match != null;
		}
		return false;
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		if (context is VTMatchOneToManyContext) {
			return true;
		}
		return false;
	}
}
